#include "gw_world_simulation.h"
#include <algorithm>
#include <iostream>
namespace {
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
bool contains(const std::vector<fw::gw::world::Packet>& batch,const fw::gw::world::Packet& packet){return std::find(batch.begin(),batch.end(),packet)!=batch.end();}
}
int main()try{
 using namespace fw::gw;world::Instance instance;auto owner=std::make_shared<world::Outbox>(),peer=std::make_shared<world::Outbox>();instance.join(1,"Emote Owner",0,0,owner);instance.join(2,"Emote Peer",10,0,peer);owner->drain();peer->drain();
 instance.emote(1,{emotes::Action::dance,false},1000);auto own=owner->drain(),other=peer->drain();check(contains(own,emotes::dance_2022(1))&&contains(other,emotes::dance_2022(1)),"dance broadcast reaches owner and peer");
 auto late=std::make_shared<world::Outbox>();auto snapshot=instance.join(3,"Late Observer",20,0,late);auto actor=std::find_if(snapshot.begin(),snapshot.end(),[](const auto& s){return s.id==1;});check(actor!=snapshot.end()&&contains(actor->presentation,emotes::dance_2022(1)),"late join sees existing dance presentation");owner->drain();peer->drain();
 instance.emote(1,{emotes::Action::sit,false},1100);own=owner->drain();other=peer->drain();check(contains(own,emotes::reset_animation_2022(1))&&contains(other,emotes::reset_animation_2022(1)),"sit cancels dance animation for all observers");check(contains(own,emotes::effects_2022(1,emotes::sitting))&&contains(other,emotes::effects_2022(1,emotes::sitting)),"sit authoritative effects broadcast");
 auto fourth=std::make_shared<world::Outbox>();snapshot=instance.join(4,"Sitting Observer",30,0,fourth);actor=std::find_if(snapshot.begin(),snapshot.end(),[](const auto& s){return s.id==1;});check(actor!=snapshot.end()&&contains(actor->presentation,emotes::effects_2022(1,emotes::sitting)),"late join sees sitting state");owner->drain();peer->drain();
 instance.emote(1,{emotes::Action::dance,false},1200);own=owner->drain();peer->drain();check(contains(own,emotes::effects_2022(1,0)),"dance clears authoritative sitting bit");instance.move(1,100,0,1210);own=owner->drain();other=peer->drain();check(contains(own,emotes::reset_animation_2022(1))&&contains(other,emotes::reset_animation_2022(1)),"click movement cancels dance on owner and peer");
 instance.emote(1,{emotes::Action::dance,false},1300);owner->drain();peer->drain();instance.steer(1,1,0,1400);own=owner->drain();other=peer->drain();check(contains(own,emotes::reset_animation_2022(1))&&contains(other,emotes::reset_animation_2022(1)),"keyboard movement cancels dance broadcast");
 instance.emote(1,{emotes::Action::dance,true},4100);own=owner->drain();peer->drain();check(!contains(own,emotes::dance_2022(1)),"synchronized dance waits for five second boundary");instance.tick(4900);own=owner->drain();peer->drain();check(!contains(own,emotes::dance_2022(1)),"world tick before sync boundary does not start dance");instance.tick(5000);own=owner->drain();other=peer->drain();check(contains(own,emotes::dance_2022(1))&&contains(other,emotes::dance_2022(1)),"world tick starts synchronized dance for both peers");instance.tick(5100);own=owner->drain();check(!contains(own,emotes::dance_2022(1)),"scheduled dance fires once");
 instance.emote(1,{emotes::Action::sit,true},6100);instance.leave(1);owner->drain();peer->drain();instance.join(1,"Reconnected Owner",0,0,owner);owner->drain();peer->drain();auto newcomer=std::make_shared<world::Outbox>();snapshot=instance.join(5,"Reconnect Observer",40,0,newcomer);actor=std::find_if(snapshot.begin(),snapshot.end(),[](const auto& s){return s.id==1;});check(actor!=snapshot.end()&&!contains(actor->presentation,emotes::dance_2022(1))&&!contains(actor->presentation,emotes::effects_2022(1,emotes::sitting)),"disconnect removes retained emote presentation");owner->drain();peer->drain();instance.tick(10000);own=owner->drain();check(!contains(own,emotes::effects_2022(1,emotes::sitting)),"scheduled emote cannot survive disconnect and reused player ID");
 std::cout<<"PASS native world emote owner/peer broadcast, late joins, click/steer cancellation, synchronized ticks and disconnect reset\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}
